import{_ as t,o as s,c as a,ak as i}from"./chunks/framework.WEfAUR5x.js";const k=JSON.parse('{"title":"Hooks","description":"","frontmatter":{},"headers":[],"relativePath":"guide/hooks.md","filePath":"guide/hooks.md","lastUpdated":1780002933000}'),n={name:"guide/hooks.md"};function o(d,e,l,r,p,h){return s(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="hooks" tabindex="-1">Hooks <a class="header-anchor" href="#hooks" aria-label="Permalink to “Hooks”">​</a></h1><p>Hooks fire when files or configs change. Pika logs every emitted event as one structured server log line by default; this can be disabled under <strong>Settings → Hooks</strong>. Hook delivery rules are not required for basic event observability. Pika also ships with four delivery sinks — HTTP webhook, Kafka, Redis Pub/Sub, and NATS — plus a configurable <code>log</code> sink for custom log messages. Hooks are managed under <strong>Settings → Hooks</strong>.</p><h2 id="event-types" tabindex="-1">Event types <a class="header-anchor" href="#event-types" aria-label="Permalink to “Event types”">​</a></h2><p>Currently emitted by pika:</p><table tabindex="0"><thead><tr><th>Event</th><th>Trigger</th></tr></thead><tbody><tr><td><code>config.created</code></td><td>Config file created via the admin API.</td></tr><tr><td><code>config.deleted</code></td><td>Config file deleted via the admin API.</td></tr><tr><td><code>vault.item.created</code></td><td>Personal-vault item created.</td></tr><tr><td><code>vault.item.updated</code></td><td>Personal-vault item updated.</td></tr><tr><td><code>vault.item.deleted</code></td><td>Personal-vault item soft-deleted.</td></tr><tr><td><code>vault.unlock.failed</code></td><td>Personal-vault unlock attempt failed (wrong master password).</td></tr><tr><td><code>*</code></td><td>Match all events.</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">Vault event payloads</p><p>Vault events carry only the item id, type, and the calling user. The encrypted payload is <strong>never</strong> included — the server cannot read it (the personal vault is end-to-end encrypted client-side).</p></div><div class="info custom-block"><p class="custom-block-title">Reserved event types</p><p><code>file.*</code>, <code>dir.*</code>, <code>config.updated</code>, and <code>registry.*</code> are declared in the event type constants but no longer emitted in this build — the raw filesystem and artifact-registry features have been extracted out of pika. Hook filters can still reference these strings; they simply won&#39;t fire.</p></div><h2 id="default-payload" tabindex="-1">Default payload <a class="header-anchor" href="#default-payload" aria-label="Permalink to “Default payload”">​</a></h2><p>All sinks receive a JSON-encoded <code>Event</code>:</p><div class="language-json"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;config.created&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;timestamp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2026-05-07T12:34:56.789Z&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;hook&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;my-hook-name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;config_key&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;myapp/config&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;config_version&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;variant&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;user&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;alice&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;protocol&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;http&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Field meanings:</p><ul><li><code>protocol</code> — how the change was made: <code>http</code> (admin API) or <code>internal</code> (cluster sync, etc.). Public-port Endpoints are read-only and never produce write events.</li><li><code>user</code> — pika username, or empty for internal/system actions.</li><li><code>config_key</code>, <code>config_version</code>, <code>variant</code> — populated for <code>config.*</code> events.</li><li>For <code>vault.item.*</code> events, <code>path</code> carries the item id and <code>user</code> is the owning user. The body of the vault item is intentionally <strong>not</strong> included.</li></ul><h2 id="filters" tabindex="-1">Filters <a class="header-anchor" href="#filters" aria-label="Permalink to “Filters”">​</a></h2><p>Each hook can be filtered before it fires:</p><ul><li><strong>Event types</strong> — pick one or more of the events above (or <code>*</code>).</li><li><strong>Path pattern</strong> — <code>filepath.Match</code> glob (e.g. <code>myapp/*</code>, <code>tenants/*/secrets</code>).</li></ul><p>A hook only fires when all filters match.</p><h2 id="targets" tabindex="-1">Targets <a class="header-anchor" href="#targets" aria-label="Permalink to “Targets”">​</a></h2><p>A single hook can dispatch to multiple targets. Each target has its own settings.</p><h3 id="http-webhook" tabindex="-1">HTTP webhook <a class="header-anchor" href="#http-webhook" aria-label="Permalink to “HTTP webhook”">​</a></h3><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Method : POST | PUT</span></span>
<span class="line"><span>URL    : https://example.com/pika-events</span></span>
<span class="line"><span>Headers: { &quot;X-Pika-Token&quot;: &quot;...&quot; }</span></span>
<span class="line"><span>Timeout: 30s</span></span></code></pre></div><p>Pika sends the rendered payload as the request body and <code>User-Agent: pika/&lt;version&gt;</code>. Non-2xx responses are retried with exponential backoff (configurable per target).</p><h3 id="kafka" tabindex="-1">Kafka <a class="header-anchor" href="#kafka" aria-label="Permalink to “Kafka”">​</a></h3><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Brokers       : kafka-1:9092, kafka-2:9092</span></span>
<span class="line"><span>Topic         : pika.events</span></span>
<span class="line"><span>Key template  : {{.Mount}}/{{.Path}}    (default — overridable)</span></span>
<span class="line"><span>TLS           : disabled | enabled (cert / key / CA)</span></span>
<span class="line"><span>SASL          : PLAIN | SCRAM-SHA-256 | SCRAM-SHA-512</span></span></code></pre></div><p>TLS material can come from disk paths, inline PEM, or <a href="#pika-references-in-tls-fields">pika references</a>.</p><h3 id="redis-pub-sub" tabindex="-1">Redis Pub/Sub <a class="header-anchor" href="#redis-pub-sub" aria-label="Permalink to “Redis Pub/Sub”">​</a></h3><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Mode      : standalone | cluster</span></span>
<span class="line"><span>Address(es): redis:6379</span></span>
<span class="line"><span>Channel   : pika.events</span></span>
<span class="line"><span>Password  : ...</span></span>
<span class="line"><span>DB        : 0</span></span>
<span class="line"><span>TLS       : optional with mTLS support</span></span></code></pre></div><h3 id="nats" tabindex="-1">NATS <a class="header-anchor" href="#nats" aria-label="Permalink to “NATS”">​</a></h3><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>URL    : nats://nats:4222</span></span>
<span class="line"><span>Subject: pika.events</span></span>
<span class="line"><span>Auth   : token | username/password</span></span></code></pre></div><h3 id="log" tabindex="-1">log <a class="header-anchor" href="#log" aria-label="Permalink to “log”">​</a></h3><p>Emits an <code>slog</code> line on the pika server. Useful while developing a payload template:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Level  : info | warn | ...</span></span>
<span class="line"><span>Message: hook fired: {{.Type}} {{.Mount}}/{{.Path}}</span></span>
<span class="line"><span>Fields : { &quot;user&quot;: &quot;{{.User}}&quot;, &quot;size&quot;: {{.Size}} }</span></span></code></pre></div><h2 id="custom-payloads" tabindex="-1">Custom payloads <a class="header-anchor" href="#custom-payloads" aria-label="Permalink to “Custom payloads”">​</a></h2><p>Each target can define a <code>body_template</code> (or <code>key_template</code> / <code>message</code> / <code>fields</code> for non-HTTP sinks) using Go&#39;s <a href="https://pkg.go.dev/text/template" target="_blank" rel="noreferrer"><code>text/template</code></a>. Available fields:</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th></tr></thead><tbody><tr><td><code>.Type</code></td><td>string</td></tr><tr><td><code>.Timestamp</code></td><td>RFC3339 string</td></tr><tr><td><code>.Hook</code></td><td>string</td></tr><tr><td><code>.Mount</code></td><td>string</td></tr><tr><td><code>.Path</code></td><td>string</td></tr><tr><td><code>.Size</code></td><td>int</td></tr><tr><td><code>.Protocol</code></td><td>string</td></tr><tr><td><code>.User</code></td><td>string</td></tr><tr><td><code>.OldPath</code></td><td>string</td></tr><tr><td><code>.DstMount</code></td><td>string</td></tr><tr><td><code>.DstPath</code></td><td>string</td></tr><tr><td><code>.ConfigKey</code></td><td>string</td></tr><tr><td><code>.ConfigVersion</code></td><td>int</td></tr><tr><td><code>.Variant</code></td><td>string</td></tr></tbody></table><p>Example HTTP body template:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>  &quot;channel&quot;: &quot;#ops&quot;,</span></span>
<span class="line"><span>  &quot;text&quot;: &quot;:package: \`{{.User}}\` uploaded \`{{.Path}}\` ({{.Size}} bytes) to \`{{.Mount}}\`&quot;</span></span>
<span class="line"><span>}</span></span></code></pre></div><h2 id="pika-references-in-tls-fields" tabindex="-1">Pika references in TLS fields <a class="header-anchor" href="#pika-references-in-tls-fields" aria-label="Permalink to “Pika references in TLS fields”">​</a></h2><p>Kafka and Redis TLS fields (cert, key, CA) accept two forms:</p><ul><li>A plain filesystem path (<code>/etc/ssl/kafka.pem</code>).</li><li>A pika config reference: <code>config://certificates/kafka</code> — the file content is read live from pika storage each time the target connects.</li></ul><p>This lets you rotate TLS material via the UI without touching the host filesystem. Legacy <code>raw://</code> references from earlier pika versions decode but resolve to inline PEM text; they will fail with a parse error if the path no longer matches a real file.</p>`,40)])])}const g=t(n,[["render",o]]);export{k as __pageData,g as default};
